contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // sendAmount is forwarded to c.play
    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        // ensure this contract has enough balance to forward sendAmount
        require(address(this).balance >= sendAmount);

        // observe before state
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted;
        // attempt the state-changing call and capture whether it reverted
        c.play{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after state
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        uint TICKET = 10;

        // General rule asserted:
        // - bank address never changes
        // - if the call reverted then sent amount was not equal to the ticket price
        // - if the call did not revert then sent amount equals the ticket price and the pot either increased by TICKET or became zero
        assert(
            bankBefore == bankAfter &&
            (
                (reverted && sendAmount != TICKET)
                ||
                (!reverted && sendAmount == TICKET && (potAfter == potBefore + TICKET || potAfter == 0))
            )
        );
    }

    // Allow receiving Ether if C pays out to this contract
    receive() external payable {}
}

